": 7, "unid": "", "foto": "/assets/img/exemplo/fornalha/lata-guarana-jesus.webp", "destaque": false, "selo": "", "opcoes": [{"id": "rl", "nome": "Sabor", "min": 1, "max": 1, "itens": [{"id": "a", "nome": "Coca-Cola", "preco": 0}, {"id": "b", "nome": "Coca-Cola Zero", "preco": 0}, {"id": "c", "nome": "Guaraná", "preco": 0}, {"id": "d", "nome": "Fanta Laranja", "preco": 0}, {"id": "e", "nome": "Sprite", "preco": 0}, {"id": "f", "nome": "Schweppes Citrus", "preco": 0}]}]}, {"nome": "Suco natural 1 litro", "desc": "Feito na hora. Laranja, limão ou maracujá.", "preco": 18, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-suco-jarra.jpg", "destaque": false, "selo": "", "opcoes": [{"id": "fruta", "nome": "Fruta", "min": 1, "max": 1, "itens": [{"id": "f1", "nome": "Laranja", "preco": 0}, {"id": "f2", "nome": "Limão", "preco": 0}, {"id": "f3", "nome": "Maracujá", "preco": 0}]}]}, {"nome": "Água mineral 500 ml", "desc": "Com ou sem gás.", "preco": 5, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-agua.jpg", "destaque": false, "selo": "", "opcoes": [{"id": "agua", "nome": "Escolha", "min": 1, "max": 1, "itens": [{"id": "g1", "nome": "Sem gás", "preco": 0}, {"id": "g2", "nome": "Com gás", "preco": 0.5}]}]}, {"nome": "Cerveja long neck 355 ml", "desc": "Trincando. Venda para maiores de 18 anos.", "preco": 12, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-cerveja.jpg", "destaque": false, "selo": "", "opcoes": [{"id": "cerv", "nome": "Cerveja", "min": 1, "max": 1, "itens": [{"id": "c1", "nome": "Heineken", "preco": 0}, {"id": "c2", "nome": "Stella Artois", "preco": 0}, {"id": "c3", "nome": "Corona", "preco": 2}]}]}, {"nome": "Cerveja 600 ml", "desc": "Para dividir. Venda para maiores de 18 anos.", "preco": 18, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-cerveja.jpg", "destaque": false, "selo": "", "opcoes": [{"id": "c6", "nome": "Cerveja", "min": 1, "max": 1, "itens": [{"id": "a", "nome": "Original", "preco": 0}, {"id": "b", "nome": "Heineken", "preco": 3}]}]}, {"nome": "Vinho tinto Casillero del Diablo", "desc": "Cabernet Sauvignon, 750 ml. Ótimo com as napoletanas.", "preco": 79, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-casillero.jpg", "destaque": false, "selo": "", "opcoes": []}, {"nome": "Vinho tinto Catena Malbec", "desc": "Malbec argentino, 750 ml.", "preco": 139, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-catena-malbec.jpg", "destaque": false, "selo": "Premium", "opcoes": []}, {"nome": "Espumante Salton Brut", "desc": "750 ml, para celebrar.", "preco": 65, "unid": "", "foto": "/assets/img/exemplo/fornalha/beb-salton-brut.jpg", "destaque": false, "selo": "", "opcoes": []}]}]'::jsonb;
  c jsonb; p jsonb; cid text; pos int := 0; k int;
begin
  select id into v_loja from public.lojas where slug = 'pizzaria';
  if v_loja is null then
    select id into v_pad from public.lojas where slug = 'padaria';
    insert into public.lojas (slug, store_name, modelo, criado_por)
    values ('pizzaria', 'Fornalha Pizzaria', 'pizzaria', (select criado_por from public.lojas where id = v_pad))
    returning id into v_loja;
    if v_pad is not null then
      insert into public.membros (loja_id, user_id, papel, email)
      select v_loja, m.user_id, m.papel, m.email from public.membros m where m.loja_id = v_pad
      on conflict (loja_id, user_id) do nothing;
    end if;
  end if;

  update public.lojas set
    store_name = 'Fornalha Pizzaria', modelo = 'pizzaria', descricao = 'Pizza no forno a lenha. Massa de fermentação longa, molho de tomate pelado e ingredientes selecionados.',
    whatsapp = '5542999006578', address = 'Rua Exemplo, 456 · Centro', hours = 'Ter a dom · 18h às 23h30',
    instagram = '@fornalhapizzaria', cor = '#B8392B',
    logo_url = '/assets/img/exemplo/fornalha/sua-logo.png', capa_url = '/assets/img/exemplo/fornalha/forno-hero.jpg',
    delivery_fee = 8.0, min_order = 0.0,
    accept_orders = true, faz_entrega = true, faz_retirada = true, pagamentos = array['Pix','Cartão','Dinheiro'], status = 'ativa',
    extra = coalesce(extra, '{}'::jsonb) || '{"secoes": {"sobre": {"titulo": "Fogo, tempo e massa", "texto": "Nossa massa descansa 48 horas antes de ir ao forno a lenha.\nO molho é de tomate pelado, a mussarela é fresca e cada pizza sai na hora, com a borda leve e alveolada.", "foto": "/assets/img/exemplo/fornalha/forno-visite.jpg"}, "galeria": {"fotos": ["/assets/img/exemplo/fornalha/calabresa.jpg", "/assets/img/exemplo/fornalha/margherita.webp", "/assets/img/exemplo/fornalha/quatro-queijos.webp", "/assets/img/exemplo/fornalha/diavola.webp", "/assets/img/exemplo/fornalha/bufala.webp", "/assets/img/exemplo/fornalha/sig-frango-grelhado.webp"]}}}'::jsonb
  where id = v_loja;

  delete from public.products where loja_id = v_loja;
  delete from public.categories where loja_id = v_loja;
  for c in select * from jsonb_array_elements(cardapio) loop
    pos := pos + 1;
    insert into public.categories (loja_id, name, position) values (v_loja, c ->> 'nome', pos) returning id into cid;
    k := 0;
    for p in select * from jsonb_array_elements(c -> 'itens') loop
      k := k + 1;
      insert into public.products (loja_id, category_id, name, description, price, unit, image_url, active, featured, badge, position, opcoes)
      values (v_loja, cid, p ->> 'nome', coalesce(p ->> 'desc', ''), (p ->> 'preco')::numeric, coalesce(p ->> 'unid', ''),
              coalesce(p ->> 'foto', ''), true, coalesce((p ->> 'destaque')::boolean, false), coalesce(p ->> 'selo', ''), k,
              coalesce(p -> 'opcoes', '[]'::jsonb));
    end loop;
  end loop;
  raise notice 'Pronto: % com % categorias e % produtos.', 'Fornalha Pizzaria', pos, (select count(*) from public.products where loja_id = v_loja);
end $$;
